// #8f268d (6edba0ceef980e18a08f268d) — cron-задачи purge-expired-recordings и close-abandoned-attempts работают:
// активны, секреты Vault заданы, проверка «последний запуск» есть (RPC admin_scheduled_jobs_health, только Super Admin).
// spec: specs/scheduled-jobs.md · seed: tests/seed.admin.spec.ts.
// Факт 04.11.2026 (прод, 12:27Z): purge «15 * * * *» active/secrets true, last 12:15 true/200;
// close-abandoned «*/10 * * * *» active/secrets true, last 12:20 true/200 (скрин 8f268d-health-prod-desktop.png).
// Только чтение (RPC без аргументов) → @prod-safe. Успех последнего запуска и его свежесть — мягкие проверки
// (один медленный прогон purge у границы 40 с — известный риск, тикет допускает).
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';

type Job = {
  job_name: string;
  schedule: string;
  active: boolean;
  secrets_configured: boolean;
  vault_secrets?: string[];
  last_run_at: string | null;
  last_run_succeeded: boolean | null;
  last_http_status: number | null;
};

const SECRETS = ['project_url', 'purge_recordings_service_key'];
const minutesAgo = (iso: string | null) => (iso ? (Date.now() - Date.parse(iso)) / 60_000 : Infinity);

test.describe('Плановые задачи — здоровье cron (#8f268d · #6edba0ceef980e18a08f268d)', () => {
  test('admin: admin_scheduled_jobs_health — purge-expired-recordings «15 * * * *», active, secrets_configured; close-abandoned-attempts active, secrets_configured @desktop @prod-safe #8f268d #6edba0ceef980e18a08f268d', async ({ asUser }) => {
    const page = await asUser('admin');
    const api = await openWithApi(page, '/admin/support');

    const res = await api.rpc('admin_scheduled_jobs_health');
    expect(res.status(), 'admin_scheduled_jobs_health под Super Admin').toBe(200);
    const body = await res.json();
    const jobs: Job[] = Array.isArray(body) ? body : (body?.jobs ?? []);
    const byName = (n: string) => jobs.find((j) => j.job_name === n);

    // purge-expired-recordings — AC: «רצות בהצלחה בכל סביבה, והגדרת הסודות שלהן מתועדת»; расписание каждый час в :15 (миграция 20261101130400).
    const purge = byName('purge-expired-recordings');
    expect(purge, `нет purge-expired-recordings в ${jobs.map((j) => j.job_name).join(', ')}`).toBeTruthy();
    expect(purge!.schedule).toBe('15 * * * *');
    expect(purge!.active).toBe(true);
    expect(purge!.secrets_configured).toBe(true);
    for (const s of SECRETS) expect.soft(purge!.vault_secrets ?? [], `секрет ${s}`).toContain(s);

    // close-abandoned-attempts — активна, секреты заданы.
    const close = byName('close-abandoned-attempts');
    expect(close, 'нет close-abandoned-attempts').toBeTruthy();
    expect(close!.active).toBe(true);
    expect(close!.secrets_configured).toBe(true);
    expect.soft(close!.schedule, 'расписание close-abandoned-attempts (04.11 — каждые 10 мин)').toBe('*/10 * * * *');

    // Мягко: последний запуск успешен и свежий («בדיקה מוודאת שהריצה המתוזמנת האחרונה הצליחה»).
    expect.soft(purge!.last_run_succeeded, 'purge: last_run_succeeded').toBe(true);
    expect.soft(purge!.last_http_status, 'purge: last_http_status').toBe(200);
    expect.soft(minutesAgo(purge!.last_run_at), `purge: last_run_at ${purge!.last_run_at} — не старше 2 ч`).toBeLessThan(120);
    expect.soft(close!.last_run_succeeded, 'close-abandoned: last_run_succeeded').toBe(true);
    expect.soft(close!.last_http_status, 'close-abandoned: last_http_status').toBe(200);
    expect.soft(minutesAgo(close!.last_run_at), `close-abandoned: last_run_at ${close!.last_run_at} — не старше 40 мин`).toBeLessThan(40);

    test.info().annotations.push({
      type: 'health',
      description: jobs.map((j) => `${j.job_name} ${j.schedule} ${j.last_run_at} ${j.last_run_succeeded}/${j.last_http_status}`).join(' | '),
    });
  });
});
